//! `apisip.toml`: the per-folder configuration, generated by `init` and
//! editable by hand.

use std::collections::BTreeMap;
use std::time::Duration;

use serde::{Deserialize, Deserializer, Serialize, Serializer};

pub const CONFIG_FILE: &str = "apisip.toml";

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Config {
    pub source: Source,
    pub destination: Destination,
    #[serde(default)]
    pub streams: Vec<StreamConfig>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Source {
    /// URL or file path of the OpenAPI spec this config was generated from.
    pub spec: String,
    pub base_url: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub auth: Option<AuthConfig>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub rate_limit: Option<RateLimit>,
    #[serde(default)]
    pub retry: RetryConfig,
    /// Streams fetched at the same time.
    #[serde(default = "default_concurrency")]
    pub concurrency: usize,
    /// Extra headers sent with every request. Values may use `${VAR}`.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub headers: BTreeMap<String, String>,
    /// Largest response body read, in MB. A larger one fails the stream.
    #[serde(default = "default_max_response_mb")]
    pub max_response_mb: u64,
    /// Most pages one stream fetches in one run; 0 for no limit.
    #[serde(default = "default_max_pages")]
    pub max_pages: u64,
    /// How far past the run start a timestamp cursor may be and still move
    /// the watermark. Later values are written but do not count.
    #[serde(
        default = "default_max_cursor_skew",
        with = "duration_str",
        skip_serializing_if = "is_default_max_cursor_skew"
    )]
    pub max_cursor_skew: Duration,
    /// Address class of each configured host name, recorded by `init`.
    /// `run` and `check` refuse a host that now resolves to another class.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub address_class: BTreeMap<String, AddressClass>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum AddressClass {
    Public,
    Private,
    Loopback,
    LinkLocal,
}

impl std::fmt::Display for AddressClass {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            AddressClass::Public => "public",
            AddressClass::Private => "private",
            AddressClass::Loopback => "loopback",
            AddressClass::LinkLocal => "link-local",
        })
    }
}

fn default_concurrency() -> usize {
    4
}

pub fn default_max_response_mb() -> u64 {
    64
}

pub fn default_max_pages() -> u64 {
    1000
}

pub fn default_max_cursor_skew() -> Duration {
    Duration::from_secs(24 * 3600)
}

fn is_default_max_cursor_skew(d: &Duration) -> bool {
    *d == default_max_cursor_skew()
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum AuthConfig {
    Bearer {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        token: String,
    },
    ApiKey {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        name: String,
        #[serde(rename = "in")]
        location: ApiKeyLocation,
        value: String,
    },
    Basic {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        username: String,
        password: String,
    },
    Oauth2ClientCredentials {
        #[serde(default, skip_serializing_if = "Option::is_none")]
        scheme: Option<String>,
        token_url: String,
        client_id: String,
        client_secret: String,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        scopes: Vec<String>,
    },
}

impl AuthConfig {
    /// Name of the security scheme in the spec, when known.
    pub fn scheme(&self) -> Option<&str> {
        match self {
            AuthConfig::Bearer { scheme, .. }
            | AuthConfig::ApiKey { scheme, .. }
            | AuthConfig::Basic { scheme, .. }
            | AuthConfig::Oauth2ClientCredentials { scheme, .. } => scheme.as_deref(),
        }
    }

    pub fn kind(&self) -> &'static str {
        match self {
            AuthConfig::Bearer { .. } => "bearer",
            AuthConfig::ApiKey { .. } => "api_key",
            AuthConfig::Basic { .. } => "basic",
            AuthConfig::Oauth2ClientCredentials { .. } => "oauth2_client_credentials",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ApiKeyLocation {
    Header,
    Query,
    Cookie,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RateLimit {
    pub max_calls: u32,
    #[serde(with = "duration_str")]
    pub period: Duration,
}

impl RateLimit {
    pub fn per_second(&self) -> f64 {
        self.max_calls as f64 / self.period.as_secs_f64().max(1e-9)
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RetryConfig {
    #[serde(default = "default_max_tries")]
    pub max_tries: u32,
    #[serde(default = "default_max_backoff", with = "duration_str")]
    pub max_backoff: Duration,
    /// The longest one request may spend waiting between its retries,
    /// `Retry-After` included: past it, the run fails at once.
    #[serde(default = "default_max_wait", with = "duration_str")]
    pub max_wait: Duration,
    #[serde(default = "default_on_status")]
    pub on_status: Vec<u16>,
}

fn default_max_tries() -> u32 {
    8
}
fn default_max_backoff() -> Duration {
    Duration::from_secs(60)
}
fn default_max_wait() -> Duration {
    Duration::from_secs(600)
}
/// Answers that may differ on the next try. 501 and 505 do not, nor does
/// any other 4xx: the request itself is wrong. 520 to 524 come from
/// Cloudflare in front of an API.
fn default_on_status() -> Vec<u16> {
    vec![408, 429, 500, 502, 503, 504, 520, 521, 522, 523, 524]
}

impl Default for RetryConfig {
    fn default() -> Self {
        RetryConfig {
            max_tries: default_max_tries(),
            max_backoff: default_max_backoff(),
            max_wait: default_max_wait(),
            on_status: default_on_status(),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Destination {
    /// `file://<dir>` (relative to this folder) or `s3://bucket/prefix`.
    #[serde(default = "default_destination")]
    pub url: String,
    #[serde(default)]
    pub format: Format,
    #[serde(default)]
    pub rotate: Rotate,
    /// S3 endpoint for S3-compatible stores; `AWS_ENDPOINT_URL` also works.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub endpoint: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub region: Option<String>,
}

impl Destination {
    /// The destination as the user wrote it, without `file://` or a trailing
    /// slash, to print the paths inside it.
    pub fn shown(&self) -> &str {
        self.url.trim_start_matches("file://").trim_end_matches('/')
    }
}

/// Data goes to `data/` inside the API folder, apart from the config.
pub const DEFAULT_DESTINATION: &str = "file://data";

fn default_destination() -> String {
    DEFAULT_DESTINATION.into()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Format {
    #[default]
    Jsonl,
    Parquet,
}

impl Format {
    pub fn extension(self) -> &'static str {
        match self {
            Format::Jsonl => "jsonl",
            Format::Parquet => "parquet",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Rotate {
    #[serde(with = "bytes_str")]
    pub max_bytes: u64,
}

impl Default for Rotate {
    fn default() -> Self {
        Rotate {
            max_bytes: 128 * 1024 * 1024,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct StreamConfig {
    pub name: String,
    pub path: String,
    #[serde(default = "yes", skip_serializing_if = "is_true")]
    pub enabled: bool,
    /// JSON pointer to the record array in the response body; empty when the body is the array.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub records: String,
    #[serde(
        default,
        skip_serializing_if = "Vec::is_empty",
        serialize_with = "ser_key",
        deserialize_with = "de_key"
    )]
    pub primary_key: Vec<String>,
    /// Fixed query parameters sent with every request.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub params: BTreeMap<String, String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pagination: Option<Pagination>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub incremental: Option<Incremental>,
    /// What to do with a value of the wrong JSON type, in Parquet output.
    #[serde(default, skip_serializing_if = "is_lossless")]
    pub cast: Cast,
}

/// `lossless` converts a value when the conversion keeps it, such as
/// `"007"` to 7 for an integer column; `exact` only when the text prints back
/// the same (`"7"`, not `"007"`); `none` quarantines the record instead.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Cast {
    #[default]
    Lossless,
    Exact,
    None,
}

fn is_lossless(c: &Cast) -> bool {
    *c == Cast::Lossless
}

fn yes() -> bool {
    true
}
fn is_true(b: &bool) -> bool {
    *b
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case", deny_unknown_fields)]
pub enum Pagination {
    /// `?page=1,2,3…`
    PageNumber {
        param: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size_param: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size: Option<u32>,
        #[serde(default = "one")]
        start: u64,
    },
    /// `?offset=0,100,200…&limit=100`
    Offset {
        param: String,
        limit_param: String,
        limit: u32,
    },
    /// The next request carries a token read from the response body.
    Cursor {
        param: String,
        /// JSON pointer to the next token in the body (e.g. `/meta/next_cursor`).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        cursor_path: Option<String>,
        /// Alternatively, a field of the last record (e.g. `id` for `starting_after`).
        #[serde(default, skip_serializing_if = "Option::is_none")]
        last_record_field: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size_param: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        size: Option<u32>,
    },
    /// The body holds the full URL of the next page.
    NextUrl { next_path: String },
    /// Follow the `Link: <…>; rel="next"` header only.
    LinkHeader,
}

fn one() -> u64 {
    1
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Incremental {
    /// Record field holding the last-modified value (dotted path for nested fields).
    pub cursor: String,
    /// Server-side filter parameter: the next run sends `param=<watermark>`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub param: Option<String>,
    /// Descending sort on the cursor, for client-side early stop.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sort: Option<Sort>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Sort {
    pub param: String,
    pub value: String,
    /// Extra parameters, such as `direction = "desc"`.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub params: BTreeMap<String, String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    Filter,
    EarlyStop,
    FullRefresh,
}

impl Mode {
    pub fn label(self) -> &'static str {
        match self {
            Mode::Filter => "filter",
            Mode::EarlyStop => "early stop",
            Mode::FullRefresh => "full refresh",
        }
    }
}

impl StreamConfig {
    pub fn mode(&self) -> Mode {
        match &self.incremental {
            Some(Incremental { param: Some(_), .. }) => Mode::Filter,
            Some(Incremental { sort: Some(_), .. }) => Mode::EarlyStop,
            _ => Mode::FullRefresh,
        }
    }

    pub fn cursor(&self) -> Option<&str> {
        self.incremental.as_ref().map(|i| i.cursor.as_str())
    }
}

fn ser_key<S: Serializer>(key: &[String], s: S) -> Result<S::Ok, S::Error> {
    if key.len() == 1 {
        key[0].serialize(s)
    } else {
        key.serialize(s)
    }
}

fn de_key<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<String>, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Key {
        One(String),
        Many(Vec<String>),
    }
    Ok(match Key::deserialize(d)? {
        Key::One(k) => vec![k],
        Key::Many(ks) => ks,
    })
}

pub mod duration_str {
    use std::time::Duration;

    use serde::{Deserialize, Deserializer, Serializer, de::Error};

    pub fn serialize<S: Serializer>(d: &Duration, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&super::format_duration(*d))
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Duration, D::Error> {
        let s = String::deserialize(d)?;
        super::parse_duration(&s).map(|(d, _)| d).ok_or_else(|| {
            D::Error::custom(format!(
                "invalid duration {s:?}: write it like \"90s\", \"10m\" or \"2h 30m\""
            ))
        })
    }
}

/// A timestamp in RFC 3339 with `Z` and 0, 3, 6 or 9 fraction digits, the
/// fewest that are exact, as `_apisip/` files have always held it. Reads any
/// RFC 3339 timestamp.
pub mod timestamp_str {
    use jiff::Timestamp;
    use serde::{Deserialize, Deserializer, Serializer, de::Error};

    pub fn text(t: &Timestamp) -> String {
        let n = t.subsec_nanosecond();
        let digits = match n {
            0 => 0,
            _ if n % 1_000_000 == 0 => 3,
            _ if n % 1_000 == 0 => 6,
            _ => 9,
        };
        format!("{t:.digits$}")
    }

    pub fn serialize<S: Serializer>(t: &Timestamp, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&text(t))
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Timestamp, D::Error> {
        let s = String::deserialize(d)?;
        s.parse().map_err(D::Error::custom)
    }

    pub mod option {
        use jiff::Timestamp;
        use serde::{Deserialize, Deserializer, Serializer};

        pub fn serialize<S: Serializer>(t: &Option<Timestamp>, s: S) -> Result<S::Ok, S::Error> {
            match t {
                Some(t) => super::serialize(t, s),
                None => s.serialize_none(),
            }
        }

        pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<Option<Timestamp>, D::Error> {
            #[derive(Deserialize)]
            struct W(#[serde(with = "super")] Timestamp);
            Ok(Option::<W>::deserialize(d)?.map(|W(t)| t))
        }
    }
}

/// A duration as apisip writes it: `1m`, `24h`, `2h 30m`.
pub fn format_duration(d: Duration) -> String {
    static PRINTER: jiff::fmt::friendly::SpanPrinter = jiff::fmt::friendly::SpanPrinter::new();
    PRINTER.unsigned_duration_to_string(&d)
}

/// Reads a duration in jiff's friendly format, or in the syntax older
/// versions read. The flag is true when the old syntax gave the value: a
/// string both read, but to different values, keeps its old value.
pub fn parse_duration(s: &str) -> Option<(Duration, bool)> {
    static PARSER: jiff::fmt::friendly::SpanParser = jiff::fmt::friendly::SpanParser::new();
    let new = PARSER
        .parse_span(s)
        .ok()
        .and_then(|span| {
            span.to_duration(jiff::SpanRelativeTo::days_are_24_hours())
                .ok()
        })
        .and_then(|d| Duration::try_from(d).ok());
    match (new, parse_legacy_duration(s)) {
        (Some(n), Some(old)) if n == old => Some((n, false)),
        (_, Some(old)) => Some((old, true)),
        (Some(n), None) => Some((n, false)),
        (None, None) => None,
    }
}

/// shortcut: the duration syntax of apisip 0.4 and older (humantime 2.4's), so
/// old configs still load, with a warning; remove it in a later release.
fn parse_legacy_duration(s: &str) -> Option<Duration> {
    let digits = |s: &str| s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
    if s == "0" {
        return Some(Duration::ZERO);
    }
    let mut rest = s.trim_start();
    if rest.is_empty() {
        return None;
    }
    let mut total: u128 = 0;
    while !rest.is_empty() {
        let n = digits(rest);
        let int: u64 = rest[..n].parse().ok()?;
        rest = &rest[n..];
        let mut frac = None;
        if let Some(r) = rest.strip_prefix('.') {
            let n = digits(r);
            frac = Some((r[..n].parse::<u64>().ok()?, 10u64.checked_pow(n as u32)?));
            rest = &r[n..];
        }
        rest = rest.trim_start();
        let n = rest
            .find(|c: char| !(c.is_ascii_alphabetic() || c == '\u{b5}'))
            .unwrap_or(rest.len());
        // Nanoseconds per unit; from hours up, a fraction counts in whole seconds.
        let (unit, whole_secs): (u64, bool) = match &rest[..n] {
            "nanos" | "nsec" | "ns" => (1, false),
            "usec" | "us" | "\u{b5}s" => (1_000, false),
            "millis" | "msec" | "ms" => (1_000_000, false),
            "seconds" | "second" | "secs" | "sec" | "s" => (1_000_000_000, false),
            "minutes" | "minute" | "min" | "mins" | "m" => (60_000_000_000, false),
            "hours" | "hour" | "hr" | "hrs" | "h" => (3_600, true),
            "days" | "day" | "d" => (86_400, true),
            "weeks" | "week" | "wk" | "wks" | "w" => (604_800, true),
            "months" | "month" | "M" => (2_630_016, true),
            "years" | "year" | "yr" | "yrs" | "y" => (31_557_600, true),
            _ => return None,
        };
        rest = rest[n..].trim_start();
        let scale: u128 = if whole_secs { 1_000_000_000 } else { 1 };
        total = total.checked_add(int as u128 * unit as u128 * scale)?;
        if let Some((num, den)) = frac {
            if unit == 1 {
                return None;
            }
            // An inexact fraction was an error; jiff reads it exactly.
            let part = num.checked_mul(unit)?;
            if part % den != 0 {
                return None;
            }
            total = total.checked_add((part / den) as u128 * scale)?;
        }
    }
    let secs = u64::try_from(total / 1_000_000_000).ok()?;
    Some(Duration::new(secs, (total % 1_000_000_000) as u32))
}

/// A duration key of apisip.toml written in the old syntax.
#[derive(Debug, Clone, PartialEq)]
pub struct LegacyDuration {
    pub key: String,
    pub old: String,
    pub new: String,
}

const DURATION_KEYS: [&[&str]; 4] = [
    &["source", "max_cursor_skew"],
    &["source", "rate_limit", "period"],
    &["source", "retry", "max_backoff"],
    &["source", "retry", "max_wait"],
];

/// The durations of apisip.toml that only the old syntax reads, and what
/// `update` rewrites them to: the same value, to the nearest hour from 1 hour
/// up, so a month does not print as `730h 29m 3s`.
pub fn legacy_durations(text: &str) -> Vec<LegacyDuration> {
    let Ok(doc) = text.parse::<toml_edit::DocumentMut>() else {
        return Vec::new();
    };
    let mut out = Vec::new();
    for path in DURATION_KEYS {
        let item = path.iter().try_fold(doc.as_item(), |i, k| i.get(k));
        let Some(old) = item.and_then(|i| i.as_str()) else {
            continue;
        };
        if let Some((d, true)) = parse_duration(old) {
            let hour = 3_600_000_000_000u128;
            let d = if d.as_nanos() >= hour {
                Duration::from_secs(((d.as_nanos() + hour / 2) / hour * 3_600) as u64)
            } else {
                d
            };
            out.push(LegacyDuration {
                key: path.join("."),
                old: old.to_string(),
                new: format_duration(d),
            });
        }
    }
    out
}

/// Rewrites the given legacy durations in place, keeping comments and layout.
pub fn rewrite_durations(text: &str, legacy: &[LegacyDuration]) -> anyhow::Result<String> {
    let mut doc = text.parse::<toml_edit::DocumentMut>()?;
    for l in legacy {
        let mut item = doc.as_item_mut();
        for k in l.key.split('.') {
            item = item
                .get_mut(k)
                .ok_or_else(|| anyhow::anyhow!("{} is missing", l.key))?;
        }
        let v = item
            .as_value_mut()
            .ok_or_else(|| anyhow::anyhow!("{} is not a value", l.key))?;
        let decor = v.decor().clone();
        *v = l.new.as_str().into();
        *v.decor_mut() = decor;
    }
    Ok(doc.to_string())
}

pub mod bytes_str {
    use serde::{Deserialize, Deserializer, Serializer, de::Error};

    pub fn serialize<S: Serializer>(b: &u64, s: S) -> Result<S::Ok, S::Error> {
        let units = [("GiB", 1u64 << 30), ("MiB", 1 << 20), ("KiB", 1 << 10)];
        let text = units
            .iter()
            .find(|(_, size)| *b >= *size && b.is_multiple_of(*size))
            .map(|(unit, size)| format!("{}{unit}", b / size))
            .unwrap_or_else(|| format!("{b}B"));
        s.serialize_str(&text)
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<u64, D::Error> {
        let s = String::deserialize(d)?;
        s.parse::<bytesize::ByteSize>()
            .map(|b| b.as_u64())
            .map_err(|e| D::Error::custom(format!("invalid size {s:?}: {e}")))
    }
}

/// Replaces every `${VAR}` with the value of `VAR` from the environment
/// (which includes `.env`, loaded at startup). A missing or empty variable is an error.
pub fn interpolate(s: &str) -> anyhow::Result<String> {
    static VAR: std::sync::LazyLock<regex::Regex> =
        std::sync::LazyLock::new(|| regex::Regex::new(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}").unwrap());
    let mut missing = Vec::new();
    let out = VAR.replace_all(s, |c: &regex::Captures| match std::env::var(&c[1]) {
        Ok(v) if !v.is_empty() => v,
        _ => {
            missing.push(c[1].to_string());
            String::new()
        }
    });
    if !missing.is_empty() {
        anyhow::bail!(
            "{} not set: fill in {} in .env",
            if missing.len() == 1 {
                "variable is"
            } else {
                "variables are"
            },
            missing.join(", ")
        );
    }
    Ok(out.into_owned())
}

/// Variable names referenced as `${VAR}` in a string.
pub fn referenced_vars(s: &str) -> Vec<String> {
    let re = regex::Regex::new(r"\$\{([A-Za-z_][A-Za-z0-9_]*)\}").unwrap();
    re.captures_iter(s).map(|c| c[1].to_string()).collect()
}

impl Config {
    pub fn parse(text: &str) -> anyhow::Result<Config> {
        let config: Config = toml::from_str(text)?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> anyhow::Result<()> {
        let mut seen = std::collections::BTreeSet::new();
        for s in &self.streams {
            if !seen.insert(&s.name) {
                anyhow::bail!("stream `{}` is defined twice", s.name);
            }
            // The name lands in a DuckDB glob path, so `*`, `?` or `[` would read other streams.
            if s.name.is_empty()
                || !s
                    .name
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
            {
                anyhow::bail!(
                    "invalid stream name {:?}: use letters, digits, `_` or `-`",
                    s.name
                );
            }
            if s.incremental.is_some() && s.primary_key.is_empty() {
                // Allowed, but the generated views need a key to deduplicate.
                tracing::debug!("stream {} has a cursor but no primary key", s.name);
            }
        }
        if self.source.concurrency == 0 {
            anyhow::bail!("source.concurrency must be at least 1");
        }
        if self.source.retry.max_tries == 0 {
            anyhow::bail!("source.retry.max_tries must be at least 1");
        }
        if self.source.max_response_mb == 0 {
            anyhow::bail!("source.max_response_mb must be at least 1");
        }
        Ok(())
    }

    /// Renders the config as TOML, with small tables inline and optional
    /// comments: a header, a note per stream, and a note before `[destination]`.
    pub fn render(
        &self,
        header: &str,
        notes: &BTreeMap<String, String>,
        source_note: Option<&str>,
    ) -> String {
        use toml_edit::{DocumentMut, Item, Value};
        let text = toml::to_string(self).expect("config serializes");
        let mut doc: DocumentMut = text.parse().expect("toml output parses");

        fn inline(table: &mut toml_edit::Table, keys: &[&str]) {
            for key in keys {
                if let Some(item) = table.get_mut(key)
                    && let Item::Table(t) = item
                {
                    let t = std::mem::take(t);
                    *item = Item::Value(Value::InlineTable(t.into_inline_table()));
                    if let Some(mut k) = table.key_mut(key) {
                        k.leaf_decor_mut().set_suffix(" ");
                    }
                }
            }
            // Keep struct order: scalars and inlined tables interleaved as declared.
            let order: Vec<String> = ORDER.iter().map(|s| s.to_string()).collect();
            table.sort_values_by(|a, _, b, _| {
                let rank = |k: &str| order.iter().position(|o| o == k).unwrap_or(usize::MAX);
                rank(a.get()).cmp(&rank(b.get()))
            });
        }
        const ORDER: [&str; 21] = [
            "spec",
            "base_url",
            "address_class",
            "auth",
            "rate_limit",
            "retry",
            "concurrency",
            "headers",
            "url",
            "format",
            "rotate",
            "endpoint",
            "region",
            "name",
            "path",
            "enabled",
            "records",
            "primary_key",
            "params",
            "pagination",
            "incremental",
        ];
        if let Some(source) = doc.get_mut("source").and_then(Item::as_table_mut) {
            inline(
                source,
                &["address_class", "auth", "rate_limit", "retry", "headers"],
            );
        }
        if let Some(dest) = doc.get_mut("destination").and_then(Item::as_table_mut) {
            inline(dest, &["rotate"]);
            if let Some(note) = source_note {
                dest.decor_mut().set_prefix(format!("{note}\n\n"));
            }
        }
        if let Some(streams) = doc
            .get_mut("streams")
            .and_then(Item::as_array_of_tables_mut)
        {
            for t in streams.iter_mut() {
                inline(t, &["params", "pagination", "incremental"]);
                let name = t
                    .get("name")
                    .and_then(Item::as_str)
                    .unwrap_or_default()
                    .to_string();
                if let Some(note) = notes.get(&name) {
                    t.decor_mut().set_prefix(format!("\n{note}\n"));
                }
            }
        }
        let body = doc.to_string();
        if header.is_empty() {
            body
        } else {
            format!("{header}\n\n{body}")
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Config {
        Config::parse(
            r#"
[source]
spec = "openapi.yaml"
base_url = "https://api.example.test"
auth = { type = "bearer", token = "${EXAMPLE_TOKEN}" }
rate_limit = { max_calls = 100, period = "1m" }

[destination]
format = "parquet"
rotate = { max_bytes = "64MiB" }

[[streams]]
name = "users"
path = "/users"
records = "/data"
primary_key = "id"
pagination = { type = "page_number", param = "page", size_param = "per_page", size = 100 }
incremental = { cursor = "updated_at", sort = { param = "sort", value = "-updated_at" } }
"#,
        )
        .unwrap()
    }

    #[test]
    fn parses_with_defaults() {
        let c = sample();
        assert_eq!(c.destination.url, "file://data");
        assert_eq!(c.destination.rotate.max_bytes, 64 << 20);
        assert_eq!(c.source.retry, RetryConfig::default());
        assert_eq!(c.source.max_response_mb, 64);
        assert_eq!(c.source.max_pages, 1000);
        assert_eq!(c.source.max_cursor_skew, Duration::from_secs(86_400));
        assert_eq!(
            c.source.rate_limit.as_ref().unwrap().period,
            Duration::from_secs(60)
        );
        assert_eq!(c.streams[0].primary_key, ["id"]);
        assert_eq!(c.streams[0].mode(), Mode::EarlyStop);
        assert!(c.streams[0].enabled);
    }

    #[test]
    fn render_round_trips_and_inlines() {
        let c = sample();
        let notes = BTreeMap::from([("users".to_string(), "# users: early stop".to_string())]);
        let text = c.render("# header", &notes, Some("# no rate limit"));
        assert!(text.starts_with("# header"));
        assert!(text.contains("auth = { type = \"bearer\""), "{text}");
        assert!(
            text.contains("pagination = { type = \"page_number\""),
            "{text}"
        );
        assert!(text.contains("# users: early stop\n[[streams]]"), "{text}");
        assert!(text.contains("max_bytes = \"64MiB\""), "{text}");
        assert_eq!(Config::parse(&text).unwrap(), c);
        assert!(
            !text.contains("max_cursor_skew"),
            "the default is not written"
        );
    }

    #[test]
    fn only_the_old_spellings_jiff_does_not_read_alike_take_the_legacy_path() {
        let legacy = ["0", "1M", "1month", "2months", "1y", "1year", "2years"];
        for (text, secs, nanos) in crate::time_tests::DURATIONS {
            let (d, old) = parse_duration(text).unwrap();
            assert_eq!(d, Duration::new(*secs, *nanos), "{text}");
            assert_eq!(old, legacy.contains(text), "{text}");
        }
        // Both read it, to different values: the old value wins, with a warning.
        assert_eq!(parse_duration("0"), Some((Duration::ZERO, true)));
        // An inexact old fraction errored; jiff's exact value is used.
        assert_eq!(
            parse_duration("0.0001h"),
            Some((Duration::from_millis(360), false))
        );
        assert_eq!(
            parse_duration("1.5h"),
            Some((Duration::from_secs(5_400), false))
        );
        assert_eq!(parse_legacy_duration("1.5ns"), None);
    }

    #[test]
    fn the_legacy_parser_reads_every_old_unit_spelling() {
        // humantime 2.4's spellings, each with its length in nanoseconds.
        let units: [(&[&str], u128); 10] = [
            (&["nanos", "nsec", "ns"], 1),
            (&["usec", "us", "\u{b5}s"], 1_000),
            (&["millis", "msec", "ms"], 1_000_000),
            (&["seconds", "second", "secs", "sec", "s"], 1_000_000_000),
            (&["minutes", "minute", "min", "mins", "m"], 60_000_000_000),
            (&["hours", "hour", "hr", "hrs", "h"], 3_600_000_000_000),
            (&["days", "day", "d"], 86_400_000_000_000),
            (&["weeks", "week", "wk", "wks", "w"], 604_800_000_000_000),
            (&["months", "month", "M"], 2_630_016_000_000_000),
            (&["years", "year", "yr", "yrs", "y"], 31_557_600_000_000_000),
        ];
        for (spellings, nanos) in units {
            for unit in spellings {
                let d = parse_legacy_duration(&format!("2{unit}")).unwrap();
                assert_eq!(d.as_nanos(), 2 * nanos, "{unit}");
            }
        }
        assert_eq!(
            parse_legacy_duration("1M 2d 3\u{b5}s"),
            Some(Duration::new(2_630_016 + 2 * 86_400, 3_000))
        );
    }

    #[test]
    fn durations_print_in_jiff_format_and_read_back() {
        for (d, text) in [
            (Duration::from_secs(60), "1m"),
            (Duration::from_secs(90), "1m 30s"),
            (Duration::from_secs(600), "10m"),
            (Duration::from_secs(86_400), "24h"),
            (Duration::from_secs(7 * 86_400), "168h"),
            (Duration::from_millis(1), "1ms"),
            (Duration::from_millis(1_500), "1s 500ms"),
        ] {
            assert_eq!(format_duration(d), text);
            assert_eq!(parse_duration(text), Some((d, false)), "{text}");
        }
    }

    #[test]
    fn max_cursor_skew_reads_a_duration_and_is_written_when_set() {
        let mut c = sample();
        c.source.max_cursor_skew = Duration::from_secs(7 * 86_400);
        let text = c.render("", &BTreeMap::new(), None);
        assert!(text.contains("max_cursor_skew = \"168h\""), "{text}");
        assert_eq!(Config::parse(&text).unwrap(), c);
    }

    #[test]
    fn rejects_unknown_fields_and_duplicates() {
        assert!(
            Config::parse("[source]\nspec='a'\nbase_url='b'\ntypo=1\n[destination]\n").is_err()
        );
        let dup = "[source]\nspec='a'\nbase_url='b'\n[destination]\n[[streams]]\nname='a'\npath='/a'\n[[streams]]\nname='a'\npath='/b'\n";
        assert!(
            Config::parse(dup)
                .unwrap_err()
                .to_string()
                .contains("twice")
        );
    }

    #[test]
    fn rejects_a_zero_max_response_mb() {
        let err =
            Config::parse("[source]\nspec='a'\nbase_url='b'\nmax_response_mb=0\n[destination]\n")
                .unwrap_err()
                .to_string();
        assert!(err.contains("max_response_mb must be at least 1"), "{err}");
    }

    #[test]
    fn stream_names_allow_only_letters_digits_underscore_dash() {
        let parse = |name: &str| {
            Config::parse(&format!(
                "[source]\nspec='a'\nbase_url='b'\n[destination]\n[[streams]]\nname='{name}'\npath='/a'\n"
            ))
        };
        for ok in ["users", "user_events", "user-events", "Users2"] {
            assert!(parse(ok).is_ok(), "{ok}");
        }
        for bad in ["", "user*", "a b", "a?", "a[b]", "a/b", "a.b", "é"] {
            let err = parse(bad).unwrap_err().to_string();
            assert!(err.contains("invalid stream name"), "{bad}: {err}");
        }
    }

    #[test]
    fn interpolation() {
        // SAFETY: test-only, single variable owned by this test.
        unsafe { std::env::set_var("APISIP_TEST_INTERP", "s3cr3t") };
        assert_eq!(
            interpolate("Bearer ${APISIP_TEST_INTERP}").unwrap(),
            "Bearer s3cr3t"
        );
        let err = interpolate("${APISIP_TEST_MISSING_ONE}")
            .unwrap_err()
            .to_string();
        assert!(
            err.contains("APISIP_TEST_MISSING_ONE") && err.contains(".env"),
            "{err}"
        );
        assert_eq!(referenced_vars("${A}:${B_2}"), ["A", "B_2"]);
    }
}
